package com.tommyknight.flinch;

import java.util.Locale;
import lombok.EqualsAndHashCode;
import lombok.Getter;

/**
 * One selectable animation.
 *
 * Equality is on the id alone, so a selection survives the combo box model being swapped out
 * while the user filters the list.
 */
@Getter
@EqualsAndHashCode(of = "id")
final class FlinchAnimation
{
	static final int NO_ANIMATION = -1;

	static final FlinchAnimation NONE = new FlinchAnimation(NO_ANIMATION, "None", "None", Group.NONE);

	enum Group
	{
		/** The "do nothing" entry. */
		NONE,
		/** Hand-picked and hand-named, listed first. */
		FAVOURITE,
		/** Everything else built on the human rig, safe on a player model. */
		PLAYER
	}

	private final int id;
	private final String displayName;
	/** The gameval constant name, surfaced as a tooltip so ids can be cross-referenced. */
	private final String gamevalName;
	private final Group group;
	/** Lowercased once at load so filtering does not re-case 14,000 strings per keystroke. */
	private final String searchKey;

	FlinchAnimation(int id, String displayName, String gamevalName, Group group)
	{
		this.id = id;
		this.displayName = displayName;
		this.gamevalName = gamevalName;
		this.group = group;
		this.searchKey = (displayName + ' ' + gamevalName + ' ' + id).toLowerCase(Locale.ROOT);
	}

	boolean matches(String lowercaseNeedle)
	{
		return searchKey.contains(lowercaseNeedle);
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.tommyknight.flinch;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.AnimationID;

/**
 * The selectable animations, loaded once from animations.tsv.
 *
 * The TSV lists every animation built on the human rig, with its gameval constant name. Reading
 * ids from data rather than naming ~1,500 constants in code keeps the plugin decoupled from
 * whichever client release it is compiled against: a renamed constant can no longer break the
 * build, and a new one does not need a code change.
 *
 * NPC and scenery animations are deliberately absent. Animations belong to a skeleton, so those
 * render as a mangled mess on a player model.
 */
@Singleton
@Slf4j
class FlinchCatalogue
{
	private static final String RESOURCE = "animations.tsv";

	/**
	 * The player emotes, pinned to the top of the list with readable names.
	 *
	 * The rest of the human rig still appears below, so nothing is lost by keeping this list to
	 * the familiar ones.
	 */
	private static final Map<Integer, String> FAVOURITES = new LinkedHashMap<>();

	static
	{
		FAVOURITES.put(AnimationID.EMOTE_AIR_GUITAR, "Air guitar");
		FAVOURITES.put(AnimationID.EMOTE_ANGRY, "Angry");
		FAVOURITES.put(AnimationID.EMOTE_BECKON, "Beckon");
		FAVOURITES.put(AnimationID.EMOTE_BLOW_KISS, "Blow kiss");
		FAVOURITES.put(AnimationID.EMOTE_BOW, "Bow");
		FAVOURITES.put(AnimationID.EMOTE_CHEER, "Cheer");
		FAVOURITES.put(AnimationID.EMOTE_CLAP, "Clap");
		FAVOURITES.put(AnimationID.EMOTE_CLIMBING_ROPE, "Climb rope");
		FAVOURITES.put(AnimationID.EMOTE_CRY, "Cry");
		FAVOURITES.put(AnimationID.EMOTE_DANCE, "Dance");
		FAVOURITES.put(AnimationID.EMOTE_DANCE_HEADBANG, "Dance (headbang)");
		FAVOURITES.put(AnimationID.EMOTE_DANCE_SCOTTISH, "Dance (Scottish)");
		FAVOURITES.put(AnimationID.EMOTE_DANCE_SPIN, "Dance (spin)");
		FAVOURITES.put(AnimationID.EMOTE_EXPLORE, "Explore");
		FAVOURITES.put(AnimationID.EMOTE_FLEX, "Flex");
		FAVOURITES.put(AnimationID.EMOTE_FREMMENIK_SALUTE, "Fremennik salute");
		FAVOURITES.put(AnimationID.EMOTE_GLASS_BOX, "Glass box");
		FAVOURITES.put(AnimationID.EMOTE_GLASS_WALL, "Glass wall");
		FAVOURITES.put(AnimationID.EMOTE_JUMP_WITH_JOY, "Jump for joy");
		FAVOURITES.put(AnimationID.EMOTE_LAUGH, "Laugh");
		FAVOURITES.put(AnimationID.EMOTE_LIGHTBULB, "Idea");
		FAVOURITES.put(AnimationID.EMOTE_MIME_LEAN, "Lean");
		FAVOURITES.put(AnimationID.EMOTE_NO, "No");
		FAVOURITES.put(AnimationID.EMOTE_PANIC, "Panic");
		FAVOURITES.put(AnimationID.EMOTE_PANIC_FLAP, "Panic (flap)");
		FAVOURITES.put(AnimationID.EMOTE_PARTY, "Party");
		FAVOURITES.put(AnimationID.EMOTE_PUSHUPS_5, "Push-ups");
		FAVOURITES.put(AnimationID.EMOTE_RUN_ON_SPOT, "Run on the spot");
		FAVOURITES.put(AnimationID.EMOTE_SHRUG, "Shrug");
		FAVOURITES.put(AnimationID.EMOTE_SITUPS_5, "Sit-ups");
		FAVOURITES.put(AnimationID.EMOTE_SLAP_HEAD, "Slap head");
		FAVOURITES.put(AnimationID.EMOTE_STAMPFEET, "Stamp");
		FAVOURITES.put(AnimationID.EMOTE_STARJUMP_5, "Star jump");
		FAVOURITES.put(AnimationID.EMOTE_THINK, "Think");
		FAVOURITES.put(AnimationID.EMOTE_TRICK, "Trick");
		FAVOURITES.put(AnimationID.EMOTE_VARLAMORE_SALUTE, "Varlamore salute");
		FAVOURITES.put(AnimationID.EMOTE_WAVE, "Wave");
		FAVOURITES.put(AnimationID.EMOTE_YA_BOO_SUCKS, "Raspberry");
		FAVOURITES.put(AnimationID.EMOTE_YAWN, "Yawn");
		FAVOURITES.put(AnimationID.EMOTE_YES, "Yes");
	}

	private final Map<Integer, FlinchAnimation> byId = new HashMap<>();
	private List<FlinchAnimation> allAnimations = Collections.emptyList();
	private boolean loaded;

	/**
	 * Every animation, ordered favourites first, then the rest of the human rig by name.
	 * Favourites first makes the familiar emotes the ones you land on when scrolling from the top.
	 */
	synchronized List<FlinchAnimation> getAllAnimations()
	{
		load();
		return allAnimations;
	}

	/**
	 * Case-insensitive substring match over the display name, the gameval name and the id.
	 * Capped, because a one-character query matches thousands of entries and only the first
	 * screenful is ever read.
	 */
	synchronized List<FlinchAnimation> search(String query, int limit)
	{
		load();

		final String needle = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
		if (needle.isEmpty())
		{
			return allAnimations;
		}

		final List<FlinchAnimation> matches = new ArrayList<>();
		for (FlinchAnimation animation : allAnimations)
		{
			if (animation.matches(needle))
			{
				matches.add(animation);
				if (matches.size() >= limit)
				{
					break;
				}
			}
		}
		return matches;
	}

	synchronized FlinchAnimation byId(int id)
	{
		if (id == FlinchAnimation.NO_ANIMATION)
		{
			return FlinchAnimation.NONE;
		}
		load();
		final FlinchAnimation animation = byId.get(id);
		return animation == null ? FlinchAnimation.NONE : animation;
	}

	private void load()
	{
		if (loaded)
		{
			return;
		}
		loaded = true;

		final Map<Integer, String> names = new LinkedHashMap<>();
		try (InputStream in = FlinchCatalogue.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("Missing animation catalogue resource {}", RESOURCE);
				buildLists(Collections.emptyList());
				return;
			}

			try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				String line;
				while ((line = reader.readLine()) != null)
				{
					final int tab = line.indexOf('\t');
					if (tab <= 0)
					{
						continue;
					}

					try
					{
						names.put(Integer.parseInt(line.substring(0, tab).trim()), line.substring(tab + 1).trim());
					}
					catch (NumberFormatException e)
					{
						// Malformed row; skip it rather than lose the whole catalogue.
						log.debug("Bad animation catalogue row: {}", line);
					}
				}
			}
		}
		catch (IOException e)
		{
			log.warn("Could not read animation catalogue", e);
		}

		final List<FlinchAnimation> player = new ArrayList<>();

		for (Map.Entry<Integer, String> entry : names.entrySet())
		{
			final int id = entry.getKey();
			if (FAVOURITES.containsKey(id))
			{
				continue;
			}

			final String gamevalName = entry.getValue();
			player.add(new FlinchAnimation(id, pretty(gamevalName), gamevalName, FlinchAnimation.Group.PLAYER));
		}

		player.sort(Comparator
			.comparing(FlinchAnimation::getDisplayName, String.CASE_INSENSITIVE_ORDER)
			.thenComparingInt(FlinchAnimation::getId));

		buildLists(player);
	}

	private void buildLists(List<FlinchAnimation> player)
	{
		final List<FlinchAnimation> favourites = new ArrayList<>();
		for (Map.Entry<Integer, String> entry : FAVOURITES.entrySet())
		{
			favourites.add(new FlinchAnimation(entry.getKey(), entry.getValue(), entry.getValue(),
				FlinchAnimation.Group.FAVOURITE));
		}

		final List<FlinchAnimation> everything = new ArrayList<>(1 + favourites.size() + player.size());
		everything.add(FlinchAnimation.NONE);
		everything.addAll(favourites);
		everything.addAll(player);
		allAnimations = Collections.unmodifiableList(everything);

		byId.clear();
		for (FlinchAnimation animation : allAnimations)
		{
			byId.putIfAbsent(animation.getId(), animation);
		}
	}

	private static String pretty(String gamevalName)
	{
		String name = gamevalName;
		if (name.startsWith("HUMAN_"))
		{
			name = name.substring("HUMAN_".length());
		}
		else if (name.startsWith("EMOTE_"))
		{
			name = name.substring("EMOTE_".length());
		}

		name = name.replace('_', ' ').toLowerCase(Locale.ROOT).trim();
		if (name.isEmpty())
		{
			return gamevalName;
		}
		return Character.toUpperCase(name.charAt(0)) + name.substring(1);
	}
}

package com.tommyknight.flinch;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(FlinchPlugin.CONFIG_GROUP)
public interface FlinchConfig extends Config
{
	@ConfigItem(
		keyName = "showSidebar",
		name = "Show sidebar button",
		description = "Show the Flinch button in the sidebar. Every other setting lives in that panel.",
		position = 1
	)
	default boolean showSidebar()
	{
		return true;
	}
}

package com.tommyknight.flinch;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.event.ActionListener;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.AbstractListModel;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.ComboBoxEditor;
import javax.swing.ComboBoxModel;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The whole UI. The config panel holds only the sidebar toggle, so every setting the user
 * cares about is here.
 */
class FlinchPanel extends PluginPanel
{
	private static final Color SECTION_COLOR = new Color(220, 138, 0);

	/** Wrapped text wider than the panel is clipped rather than wrapped, so it is set explicitly. */
	private static final int TEXT_WIDTH = 165;

	/** A one-character query matches thousands of entries; only the first screenful is ever read. */
	private static final int MAX_SEARCH_RESULTS = 250;

	/** Fixes the combo box cell width up front so Swing never measures all 1,500 rows. */
	private static final FlinchAnimation PROTOTYPE =
		new FlinchAnimation(-2, "Wwwwwwwwwwwwwwwwwwww", "", FlinchAnimation.Group.NONE);

	private final FlinchCatalogue catalogue;

	private FlinchPlugin plugin;

	private final JCheckBox enabledBox = new JCheckBox("Enabled");
	private final JCheckBox animationCancelBox = new JCheckBox("Animation cancel");
	private final JLabel loggedOutLabel = new JLabel("Log in to preview animations.");
	private final JPanel loggedOutRow;

	private final Map<FlinchTrigger, JComboBox<FlinchAnimation>> combos = new EnumMap<>(FlinchTrigger.class);

	/** Set while the panel writes its own widgets, so listeners don't echo back into config. */
	private boolean loading;

	@Inject
	FlinchPanel(FlinchCatalogue catalogue)
	{
		super(false);
		this.catalogue = catalogue;

		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		final JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		// The sidebar reserves room for a scroll bar on the right whether or not one is showing,
		// so the right inset is larger than the left to keep the gap looking even.
		content.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 24));

		content.add(row(title(), 0));
		content.add(row(enabledBox, 10));
		content.add(row(animationCancelBox, 6));
		content.add(row(hint("Holds the animation against your own attack swings instead of "
			+ "letting them cut it short. Moving still cancels it."), 0));

		loggedOutLabel.setFont(FontManager.getRunescapeSmallFont());
		loggedOutLabel.setForeground(SECTION_COLOR);
		loggedOutRow = row(loggedOutLabel, 8);
		content.add(loggedOutRow);

		FlinchTrigger.Section current = null;
		for (FlinchTrigger trigger : FlinchTrigger.values())
		{
			if (trigger.getSection() != current)
			{
				current = trigger.getSection();
				content.add(row(sectionHeader(current.displayName), 14));
			}

			content.add(row(triggerRow(trigger), 8));
		}

		final JScrollPane scroll = new JScrollPane(content);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.setBackground(ColorScheme.DARK_GRAY_COLOR);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll, BorderLayout.CENTER);

		enabledBox.addActionListener(e ->
		{
			if (!loading && plugin != null)
			{
				plugin.setEnabled(enabledBox.isSelected());
			}
		});

		animationCancelBox.addActionListener(e ->
		{
			if (!loading && plugin != null)
			{
				plugin.setAnimationCancel(animationCancelBox.isSelected());
			}
		});
	}

	void init(FlinchPlugin plugin)
	{
		this.plugin = plugin;
		reload();
	}

	@Override
	public void onActivate()
	{
		super.onActivate();
		reload();
	}

	/** Pulls every widget's state back from config. */
	void reload()
	{
		if (plugin == null)
		{
			return;
		}

		SwingUtilities.invokeLater(() ->
		{
			loading = true;
			try
			{
				enabledBox.setSelected(plugin.isEnabled());
				animationCancelBox.setSelected(plugin.isAnimationCancel());

				final Map<FlinchTrigger, FlinchAnimation> animations = plugin.getAllAnimations();
				for (Map.Entry<FlinchTrigger, JComboBox<FlinchAnimation>> entry : combos.entrySet())
				{
					final JComboBox<FlinchAnimation> combo = entry.getValue();
					final FlinchAnimation animation = animations.get(entry.getKey());
					((FilterModel) combo.getModel()).clearFilter();
					combo.setSelectedItem(animation);
					combo.setToolTipText(describe(animation));
				}
			}
			finally
			{
				loading = false;
			}
		});
	}

	void setLoggedIn(boolean loggedIn)
	{
		SwingUtilities.invokeLater(() ->
		{
			loggedOutRow.setVisible(!loggedIn);
			revalidate();
			repaint();
		});
	}

	// --- Search ---

	/** Whether the user is mid-query, during which the combo must not rewrite the editor. */
	private static final class SearchState
	{
		private boolean typing;
	}

	/** Drops any query, restores the full list, and shows what is actually saved. */
	private void endSearch(JComboBox<FlinchAnimation> combo, FilterModel model,
		FlinchTrigger trigger, SearchState search)
	{
		search.typing = false;

		if (plugin == null)
		{
			return;
		}

		loading = true;
		try
		{
			model.clearFilter();

			// Whatever is on screen wins, and is written back on the way out. Reading the
			// stored value here instead would silently roll a fresh choice back to the old one
			// if its change event had not been recorded for any reason.
			final Object selected = combo.getSelectedItem();
			final FlinchAnimation animation = selected instanceof FlinchAnimation
				? (FlinchAnimation) selected
				: plugin.getAllAnimations().get(trigger);

			plugin.setAnimationId(trigger, animation.getId());
			combo.setSelectedItem(animation);
			// Explicit, because setSelectedItem is a no-op when the selection has not changed
			// and the editor would otherwise keep showing the abandoned query.
			combo.getEditor().setItem(animation);
			combo.setToolTipText(describe(animation));
		}
		finally
		{
			loading = false;
		}
	}

	/**
	 * A combo box model that can narrow itself to a subset without being replaced.
	 *
	 * Swapping in a whole new model resets the combo's editor, which fires document events,
	 * which filter again, an infinite loop. Filtering in place leaves the editor alone and
	 * only tells the popup its contents changed.
	 */
	private static final class FilterModel extends AbstractListModel<FlinchAnimation>
		implements ComboBoxModel<FlinchAnimation>
	{
		private final FlinchCatalogue catalogue;
		private List<FlinchAnimation> visible;
		private Object selected;

		FilterModel(FlinchCatalogue catalogue)
		{
			this.catalogue = catalogue;
			this.visible = catalogue.getAllAnimations();
		}

		boolean setFilter(String query)
		{
			final List<FlinchAnimation> next = catalogue.search(query, MAX_SEARCH_RESULTS);
			final int previousSize = visible.size();
			visible = next;
			fireContentsChanged(this, 0, Math.max(previousSize, visible.size()));
			return !visible.isEmpty();
		}

		void clearFilter()
		{
			setFilter("");
		}

		@Override
		public int getSize()
		{
			return visible.size();
		}

		@Override
		public FlinchAnimation getElementAt(int index)
		{
			return visible.get(index);
		}

		@Override
		public void setSelectedItem(Object item)
		{
			if (selected == null ? item == null : selected.equals(item))
			{
				return;
			}
			selected = item;
			// Same signal DefaultComboBoxModel sends; this is what raises the combo's action event.
			fireContentsChanged(this, -1, -1);
		}

		@Override
		public Object getSelectedItem()
		{
			return selected;
		}
	}

	// --- Construction helpers ---

	private static String describe(FlinchAnimation animation)
	{
		if (animation == null || animation.getId() == FlinchAnimation.NO_ANIMATION)
		{
			return "No animation";
		}
		return animation.getGamevalName() + " (" + animation.getId() + ")";
	}

	private static JLabel title()
	{
		final JLabel label = new JLabel("Flinch");
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(Color.WHITE);
		label.setHorizontalAlignment(SwingConstants.LEFT);
		return label;
	}

	private static JLabel sectionHeader(String text)
	{
		final JLabel label = new JLabel(text.toUpperCase());
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(SECTION_COLOR);
		label.setHorizontalAlignment(SwingConstants.LEFT);
		label.setBorder(BorderFactory.createCompoundBorder(
			new MatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(0, 0, 3, 0)));
		return label;
	}

	private static JLabel hint(String text)
	{
		// JLabel does not wrap; HTML with an explicit width is the standard Swing workaround.
		final JLabel label = new JLabel("<html><body style='width:" + TEXT_WIDTH + "px'>" + text + "</body></html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setHorizontalAlignment(SwingConstants.LEFT);
		return label;
	}

	private JPanel triggerRow(FlinchTrigger trigger)
	{
		final JLabel label = new JLabel(trigger.getDisplayName());
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Color.WHITE);
		label.setHorizontalAlignment(SwingConstants.LEFT);
		label.setToolTipText(trigger.getTooltip());
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 2, 0));

		// Editable so the entry can be typed into to filter. Arrow keys still move the
		// selection, which is how previewing by scrubbing works.
		final FilterModel model = new FilterModel(catalogue);
		final JComboBox<FlinchAnimation> combo = new JComboBox<>(model);
		combo.setEditable(true);
		combo.setMaximumRowCount(12);
		combo.setPrototypeDisplayValue(PROTOTYPE);
		combos.put(trigger, combo);

		final JTextField editor = (JTextField) combo.getEditor().getEditorComponent();
		editor.setToolTipText("Type to search, or use the up and down arrow keys to preview");

		// While the user is typing, the combo must stop writing the selected animation's name
		// back into the editor. Otherwise each keystroke restores the old text and appends to
		// it, and deleting is impossible because the name reappears. The look and feel's own
		// editor component is kept so the field still looks native; only setItem is gated.
		final SearchState search = new SearchState();
		final ComboBoxEditor delegate = combo.getEditor();
		combo.setEditor(new ComboBoxEditor()
		{
			@Override
			public Component getEditorComponent()
			{
				return delegate.getEditorComponent();
			}

			@Override
			public void setItem(Object item)
			{
				if (!search.typing)
				{
					delegate.setItem(item);
				}
			}

			@Override
			public Object getItem()
			{
				return delegate.getItem();
			}

			@Override
			public void selectAll()
			{
				delegate.selectAll();
			}

			@Override
			public void addActionListener(ActionListener l)
			{
				delegate.addActionListener(l);
			}

			@Override
			public void removeActionListener(ActionListener l)
			{
				delegate.removeActionListener(l);
			}
		});

		combo.addActionListener(e ->
		{
			if (loading || plugin == null)
			{
				return;
			}

			final Object selected = combo.getSelectedItem();
			if (!(selected instanceof FlinchAnimation))
			{
				return;
			}

			final FlinchAnimation animation = (FlinchAnimation) selected;
			plugin.setAnimationId(trigger, animation.getId());
			combo.setToolTipText(describe(animation));

			// An open popup means the user is still arrowing through results; a closed one
			// means they committed, so the search ends and the editor shows the choice.
			if (!combo.isPopupVisible())
			{
				search.typing = false;
				combo.getEditor().setItem(animation);
			}

			// Play on every change so arrowing through the list previews as it goes.
			plugin.play(animation.getId());
		});

		// Filtering hangs off real key presses rather than the editor's document, so a
		// programmatic selection, which also rewrites the editor text, never narrows the
		// list. Navigation keys are ignored for the same reason: arrowing through results
		// must not re-filter to whatever the highlighted entry happens to be called.
		editor.addKeyListener(new KeyAdapter()
		{
			@Override
			public void keyReleased(KeyEvent e)
			{
				switch (e.getKeyCode())
				{
					case KeyEvent.VK_UP:
					case KeyEvent.VK_DOWN:
					case KeyEvent.VK_LEFT:
					case KeyEvent.VK_RIGHT:
					case KeyEvent.VK_PAGE_UP:
					case KeyEvent.VK_PAGE_DOWN:
					case KeyEvent.VK_TAB:
						return;

					case KeyEvent.VK_ENTER:
					case KeyEvent.VK_ESCAPE:
						// Arrowing onto an entry already saved it, so there is nothing pending
						// to commit or discard, so both keys just end the search.
						endSearch(combo, model, trigger, search);
						return;

					default:
						break;
				}

				search.typing = true;
				final boolean anyMatches = model.setFilter(editor.getText());

				// Showing a popup throws if the panel is not on screen yet.
				if (combo.isShowing())
				{
					combo.setPopupVisible(anyMatches);
				}
			}
		});

		editor.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusGained(FocusEvent e)
			{
				// Select the existing text so the first keystroke replaces it rather than
				// appending to the name of whatever is already chosen.
				editor.selectAll();
			}
		});

		editor.addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				// Leaving a half-typed query behind would strand the dropdown on a filtered
				// list, so the full one is put back with whatever is actually saved selected.
				endSearch(combo, model, trigger, search);
			}
		});

		final JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		wrapper.add(label, BorderLayout.NORTH);
		wrapper.add(combo, BorderLayout.CENTER);
		return wrapper;
	}

	/**
	 * Wraps a component for the vertical stack.
	 *
	 * BoxLayout positions children by their alignmentX, so a stack that mixes defaults ends up
	 * visibly ragged, so every row has to declare the same alignment. It also honours maximum
	 * size, so an uncapped row stretches to fill spare vertical space. Gaps are borders rather
	 * than strut components for the same alignment reason.
	 */
	private static JPanel row(Component component, int gapTop)
	{
		final JPanel panel = new JPanel(new BorderLayout())
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		panel.setAlignmentX(LEFT_ALIGNMENT);
		panel.setBorder(BorderFactory.createEmptyBorder(gapTop, 0, 0, 0));
		panel.add(component, BorderLayout.CENTER);
		return panel;
	}
}

package com.tommyknight.flinch;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
	name = "Flinch",
	description = "Play an emote or dodge animation on yourself when you take a 0, take damage or get poisoned",
	tags = {"animation", "emote", "dodge", "hitsplat", "cosmetic", "flinch"}
)
@Slf4j
public class FlinchPlugin extends Plugin
{
	static final String CONFIG_GROUP = "flinch";

	private static final String KEY_ENABLED = "enabled";
	private static final String KEY_ANIMATION_CANCEL = "animationCancel";
	private static final String KEY_ANIMATION_PREFIX = "anim_";

	/** A game tick is 600ms; animation frame lengths are counted in 20ms client cycles. */
	private static final int CYCLES_PER_TICK = 30;
	private static final int MIN_RESET_TICKS = 1;
	/** Nothing may hold the player hostage for longer than this, whatever the frame data says. */
	private static final int MAX_RESET_TICKS = 25;

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ConfigManager configManager;
	@Inject private ClientToolbar clientToolbar;
	@Inject private FlinchCatalogue catalogue;
	@Inject private FlinchConfig config;

	private FlinchPanel panel;
	private NavigationButton navButton;
	private boolean navButtonAdded;

	/**
	 * Set when a hitsplat lands, applied on the following GameTick.
	 *
	 * Being hit makes the server play the weapon's block animation, and that arrives in the
	 * same update packet as the hitsplat, so anything applied from the hitsplat handler is
	 * immediately overwritten. GameTick is posted once that packet has been fully processed,
	 * which is the first moment our animation can survive.
	 */
	private int pendingAnimationId = FlinchAnimation.NO_ANIMATION;

	/** Guards against multi-hitsplat attacks (Scythe, chinning) retriggering within one tick. */
	private int lastTriggerTick = -1;

	/**
	 * Many animations hold their final frame instead of ending. The death poses leave you face
	 * down, and Uri's vanish leaves you invisible. The client only restores the idle pose when
	 * the animation is cleared, so we clear it ourselves once it has had time to play out.
	 */
	private int activeAnimationId = FlinchAnimation.NO_ANIMATION;
	private int animationStartTick = -1;
	private int resetAtTick = -1;

	/** Last known position, used to spot the player walking out from under an animation. */
	private WorldPoint lastLocation;

	@Provides
	FlinchConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FlinchConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = injector.getInstance(FlinchPanel.class);
		panel.init(this);

		final BufferedImage icon = ImageUtil.loadImageResource(FlinchPlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Flinch")
			.icon(icon)
			.priority(8)
			.panel(panel)
			.build();

		updateNavButton();
		panel.setLoggedIn(client.getGameState() == GameState.LOGGED_IN);
	}

	@Override
	protected void shutDown()
	{
		clearActiveAnimation();

		if (navButtonAdded)
		{
			clientToolbar.removeNavigation(navButton);
			navButtonAdded = false;
		}
		navButton = null;
		panel = null;
		lastTriggerTick = -1;
		pendingAnimationId = FlinchAnimation.NO_ANIMATION;
	}

	// --- Events ---

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CONFIG_GROUP.equals(event.getGroup()) && "showSidebar".equals(event.getKey()))
		{
			updateNavButton();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			activeAnimationId = FlinchAnimation.NO_ANIMATION;
			pendingAnimationId = FlinchAnimation.NO_ANIMATION;
			resetAtTick = -1;
			lastLocation = null;
		}

		if (panel != null)
		{
			panel.setLoggedIn(event.getGameState() == GameState.LOGGED_IN);
		}
	}

	/**
	 * Any click is treated as the user taking control back.
	 *
	 * Some animations stall movement for as long as they run, so there has to be a way out that
	 * does not involve waiting. Clicking to walk, attack or interact clears the animation
	 * immediately, whatever the animation cancel setting says.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		pendingAnimationId = FlinchAnimation.NO_ANIMATION;
		clearActiveAnimation();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (pendingAnimationId != FlinchAnimation.NO_ANIMATION)
		{
			final int animationId = pendingAnimationId;
			pendingAnimationId = FlinchAnimation.NO_ANIMATION;
			applyAnimation(animationId);
			lastLocation = location();
			return;
		}

		// Walking out from under an animation counts as taking control back too, because the click that
		// started the walk may have happened before the animation did.
		final WorldPoint location = location();
		final boolean moved = location != null && lastLocation != null && !location.equals(lastLocation);
		lastLocation = location;

		if (activeAnimationId == FlinchAnimation.NO_ANIMATION)
		{
			return;
		}

		if (moved || client.getTickCount() >= resetAtTick)
		{
			clearActiveAnimation();
			return;
		}

		if (isAnimationCancel())
		{
			holdAnimation();
		}
	}

	/**
	 * Takes the animation back when something else has claimed it mid-play.
	 *
	 * A fast weapon swings again before a flinch has finished, and the attack animation wins
	 * because it arrives later. With animation cancel on the flinch is meant to be the thing
	 * that wins, so it is re-applied at the frame it would have reached, not from the start,
	 * so it plays through once rather than stuttering back to the beginning on every swing.
	 */
	private void holdAnimation()
	{
		final Player local = client.getLocalPlayer();
		if (local == null || local.getAnimation() == activeAnimationId)
		{
			return;
		}

		final int elapsedCycles = (client.getTickCount() - animationStartTick) * CYCLES_PER_TICK;
		local.setAnimation(activeAnimationId);
		local.setAnimationFrame(frameAt(activeAnimationId, elapsedCycles));
	}

	/** The frame an animation would be showing this many client cycles in. */
	private int frameAt(int animationId, int elapsedCycles)
	{
		final Animation animation = client.loadAnimation(animationId);
		if (animation == null || animation.isMayaAnim())
		{
			return 0;
		}

		final int[] frameLengths = animation.getFrameLengths();
		if (frameLengths == null || frameLengths.length == 0)
		{
			return 0;
		}

		int remaining = elapsedCycles;
		for (int frame = 0; frame < frameLengths.length; frame++)
		{
			if (remaining < frameLengths[frame])
			{
				return frame;
			}
			remaining -= frameLengths[frame];
		}
		return frameLengths.length - 1;
	}

	private WorldPoint location()
	{
		final Player local = client.getLocalPlayer();
		return local == null ? null : local.getWorldLocation();
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!isEnabled() || event.getActor() != client.getLocalPlayer())
		{
			return;
		}

		final FlinchTrigger trigger = classify(event.getHitsplat());
		if (trigger != null)
		{
			fire(trigger);
		}
	}

	// --- Trigger resolution ---

	private FlinchTrigger classify(Hitsplat hitsplat)
	{
		switch (hitsplat.getHitsplatType())
		{
			case HitsplatID.POISON:
				return FlinchTrigger.POISON;
			case HitsplatID.VENOM:
				return FlinchTrigger.VENOM;
			case HitsplatID.HEAL:
				return FlinchTrigger.HEAL;
			default:
				break;
		}

		if (!isDamageToPlayer(hitsplat.getHitsplatType()))
		{
			return null;
		}

		return hitsplat.getAmount() <= 0 ? FlinchTrigger.ZERO : FlinchTrigger.DAMAGE;
	}

	/**
	 * Only the "me" hitsplat families land on the local player. Everything else, such as prayer drain,
	 * disease, corruption and stat changes, has its own type and must not count as damage.
	 */
	private static boolean isDamageToPlayer(int hitsplatType)
	{
		switch (hitsplatType)
		{
			case HitsplatID.BLOCK_ME:
			case HitsplatID.DAMAGE_ME:
			case HitsplatID.DAMAGE_ME_CYAN:
			case HitsplatID.DAMAGE_ME_ORANGE:
			case HitsplatID.DAMAGE_ME_YELLOW:
			case HitsplatID.DAMAGE_ME_WHITE:
			case HitsplatID.DAMAGE_ME_POISE:
			case HitsplatID.DAMAGE_MAX_ME:
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
			case HitsplatID.DAMAGE_MAX_ME_POISE:
				return true;
			default:
				return false;
		}
	}

	private void fire(FlinchTrigger trigger)
	{
		final int animationId = getAnimationId(trigger);
		if (animationId == FlinchAnimation.NO_ANIMATION)
		{
			return;
		}

		final int tick = client.getTickCount();
		if (tick == lastTriggerTick)
		{
			return;
		}

		// With animation cancel off, a flinch already playing is allowed to finish rather than
		// being restarted by the next hit. The server's own block animation is never treated as
		// a reason to skip, because replacing it is the entire feature.
		if (!isAnimationCancel() && activeAnimationId != FlinchAnimation.NO_ANIMATION)
		{
			return;
		}

		lastTriggerTick = tick;
		pendingAnimationId = animationId;
	}

	/** Plays an animation right now. Used by the panel to preview. Safe to call off the client thread. */
	void play(int animationId)
	{
		clientThread.invoke(() -> applyAnimation(animationId));
	}

	private void applyAnimation(int animationId)
	{
		clientThread.invoke(() ->
		{
			final Player local = client.getLocalPlayer();
			if (local == null)
			{
				return;
			}

			if (animationId == FlinchAnimation.NO_ANIMATION)
			{
				clearActiveAnimation();
				return;
			}

			// Clear first so a held pose is replaced outright rather than the new animation
			// being ignored because one is already running.
			local.setAnimation(FlinchAnimation.NO_ANIMATION);
			local.setAnimation(animationId);
			local.setAnimationFrame(0);

			activeAnimationId = animationId;
			animationStartTick = client.getTickCount();
			resetAtTick = animationStartTick + durationTicks(animationId);
		});
	}

	/**
	 * How long the animation runs, in game ticks, rounded up and capped. Falls back to the cap
	 * when the sequence has not been loaded from the cache yet and its frame data is unavailable.
	 */
	private int durationTicks(int animationId)
	{
		int cycles = 0;

		final Animation animation = client.loadAnimation(animationId);
		if (animation != null)
		{
			if (animation.isMayaAnim())
			{
				cycles = animation.getDuration();
			}
			else
			{
				final int[] frameLengths = animation.getFrameLengths();
				if (frameLengths != null)
				{
					for (int length : frameLengths)
					{
						cycles += length;
					}
				}
			}
		}

		if (cycles <= 0)
		{
			return MAX_RESET_TICKS;
		}

		final int ticks = (cycles + CYCLES_PER_TICK - 1) / CYCLES_PER_TICK;
		return Math.max(MIN_RESET_TICKS, Math.min(MAX_RESET_TICKS, ticks + 1));
	}

	/** Restores the idle pose, but only if the animation we started is still the one playing. */
	private void clearActiveAnimation()
	{
		final int animationId = activeAnimationId;
		activeAnimationId = FlinchAnimation.NO_ANIMATION;
		animationStartTick = -1;
		resetAtTick = -1;

		if (animationId == FlinchAnimation.NO_ANIMATION)
		{
			return;
		}

		clientThread.invoke(() ->
		{
			final Player local = client.getLocalPlayer();
			if (local != null && local.getAnimation() == animationId)
			{
				local.setAnimation(FlinchAnimation.NO_ANIMATION);
			}
		});
	}

	// --- Settings, persisted through ConfigManager rather than @ConfigItem ---
	// The panel is the whole UI, so these keys are deliberately not rendered in the
	// config panel. They still save and sync like any other config value.

	boolean isEnabled()
	{
		return getBoolean(KEY_ENABLED, true);
	}

	void setEnabled(boolean enabled)
	{
		configManager.setConfiguration(CONFIG_GROUP, KEY_ENABLED, enabled);
	}

	boolean isAnimationCancel()
	{
		return getBoolean(KEY_ANIMATION_CANCEL, false);
	}

	void setAnimationCancel(boolean cancel)
	{
		configManager.setConfiguration(CONFIG_GROUP, KEY_ANIMATION_CANCEL, cancel);
	}

	int getAnimationId(FlinchTrigger trigger)
	{
		final String stored = configManager.getConfiguration(CONFIG_GROUP, KEY_ANIMATION_PREFIX + trigger.getConfigKey());
		if (stored == null)
		{
			return trigger.getDefaultAnimationId();
		}

		try
		{
			final int animationId = Integer.parseInt(stored.trim());

			// An id the catalogue no longer knows, such as an NPC animation saved by an older
			// build, is treated as unset. Without this the panel shows None while the trigger
			// quietly keeps playing the animation that is no longer selectable.
			if (animationId != FlinchAnimation.NO_ANIMATION
				&& catalogue.byId(animationId).getId() == FlinchAnimation.NO_ANIMATION)
			{
				log.debug("Dropping unknown stored animation {} for trigger {}", animationId, trigger);
				return trigger.getDefaultAnimationId();
			}

			return animationId;
		}
		catch (NumberFormatException e)
		{
			// Pre-release builds stored an enum name here. Fall back rather than throw.
			log.debug("Unreadable stored animation '{}' for trigger {}", stored, trigger);
			return trigger.getDefaultAnimationId();
		}
	}

	void setAnimationId(FlinchTrigger trigger, int animationId)
	{
		configManager.setConfiguration(CONFIG_GROUP, KEY_ANIMATION_PREFIX + trigger.getConfigKey(), animationId);
	}

	Map<FlinchTrigger, FlinchAnimation> getAllAnimations()
	{
		final Map<FlinchTrigger, FlinchAnimation> animations = new EnumMap<>(FlinchTrigger.class);
		for (FlinchTrigger trigger : FlinchTrigger.values())
		{
			animations.put(trigger, catalogue.byId(getAnimationId(trigger)));
		}
		return animations;
	}

	private boolean getBoolean(String key, boolean fallback)
	{
		final Boolean stored = configManager.getConfiguration(CONFIG_GROUP, key, Boolean.class);
		return stored == null ? fallback : stored;
	}

	private void updateNavButton()
	{
		if (navButton == null)
		{
			return;
		}

		final boolean show = config.showSidebar();
		if (show && !navButtonAdded)
		{
			clientToolbar.addNavigation(navButton);
			navButtonAdded = true;
		}
		else if (!show && navButtonAdded)
		{
			clientToolbar.removeNavigation(navButton);
			navButtonAdded = false;
		}
	}
}

package com.tommyknight.flinch;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.AnimationID;

/**
 * The events that can play an animation, and the default each starts on.
 *
 * The config key is persisted, so renaming one silently resets that trigger for every
 * existing user. Add new triggers rather than repurposing old keys.
 */
@Getter
@RequiredArgsConstructor
enum FlinchTrigger
{
	ZERO("Block", "zero", Section.COMBAT, AnimationID.HUMAN_REAL_SWIMMING_CLIMB_ANCHOR,
		"A 0 or a blocked hit"),
	DAMAGE("Damage", "damage", Section.COMBAT, FlinchAnimation.NO_ANIMATION,
		"Any hit above 0"),

	POISON("Poison", "poison", Section.STATUS, FlinchAnimation.NO_ANIMATION,
		"Poison damage"),
	VENOM("Venom", "venom", Section.STATUS, FlinchAnimation.NO_ANIMATION,
		"Venom damage"),
	HEAL("Heal", "heal", Section.STATUS, FlinchAnimation.NO_ANIMATION,
		"Being healed");

	enum Section
	{
		COMBAT("Combat"),
		STATUS("Status");

		final String displayName;

		Section(String displayName)
		{
			this.displayName = displayName;
		}
	}

	private final String displayName;
	private final String configKey;
	private final Section section;
	private final int defaultAnimationId;
	private final String tooltip;
}

